function jenisSegitiga(a, b, c) {
  if (a <= 0 || b <= 0 || c <= 0) return "bukan segitiga";
  if (a + b <= c || a + c <= b || b + c <= a) return "bukan segitiga";
  if (a === b && b === c) return "sama sisi";
  if (a === b || b === c || a === c) return "sama kaki";
  return "sembarang";
}

