def jenis_segitiga(a, b, c):
    x, y, z = sorted([a, b, c])
    if x <= 0 or x + y <= z:
        return "bukan segitiga"
    if x == z:
        return "sama sisi"
    if x == y or y == z:
        return "sama kaki"
    return "sembarang"
